window.bookSummaryJSON = "<p>ECPA best-selling author Mindy Starns Clark continues her Million Dollar Mystery series with <i>A Dime a Dozen</i>. Private investigator Callie Webber finally meets her boss, and is immediately smitten. But the romance must wait until she solves another mystery, this time involving her late husband’s family. Callie can only hope that her prayers will be answered.</p>"; 
